[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper must pick up the available cart at the entrance station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)",
        "standing_at_available_entrance_cart": {
          "and": [
            "at_entrance_cart_station",
            "entrance_cart_available"
          ]
        }
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "standing_at_available_entrance_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "cart_required_for_item_pickup",
    "text": "Items may only be picked up while the shopper is pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "with_cart"
            ]
          },
          "post": "hasCart"
        },
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
