              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "return_cart_to_nw"
    }
  },
  {
    "id": "leave_cart_only_at_return",
