            ]
          },
          "post": "cartAt(0,1)"
        },
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_designated_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "Shoppers must exit the store on foot rather than pushing a cart through the exit.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "with_cart": "hasCart",
        "on_foot": {
          "not": "hasCart"
        }
      },
      "events": {
        "exit_on_foot": {
          "pre": {
            "and": [
              "EXIT",
              "exit_cell",
              "on_foot"
            ]
          },
          "post": null
        },
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
