    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "cart_returned_to_nw": "cartAt(0,1)"
      },
      "events": {
        "store_exit": {
          "pre": {
            "and": [
              "EXIT",
              "exit_cell"
            ]
          },
          "post": null
        }
      }
