        "nw_cart_return_station": "at(0,1)"
      },
      "events": {
        "proper_nw_cart_return": {
          "pre": {
            "and": [
              "nw_cart_return_station",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        },
        "improper_nw_interaction": {
          "pre": {
            "and": [
              "nw_cart_return_station",
              "INTERACT",
              {
                "not": "LEAVE_CART"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_nw_interaction"
    }
  }
